"""Additional checks whose behavior is gated by auditor persona."""
import re


def auditor_findings(text, path):
    """Detect direct use of self-hosted runners for the auditor persona."""
    from audit import _finding

    findings = []
    lines = text.splitlines()
    offsets = []
    offset = 0
    for line in lines:
        offsets.append(offset)
        offset += len(line.encode("utf-8")) + 1
    jobs = []
    for i, line in enumerate(lines):
        job = re.match(r"^  ([\w-]+):\s*(?:#.*)?$", line)
        if job and i and any(re.match(r"^jobs\s*:", prev) for prev in lines[:i]):
            jobs.append((job.group(1), i))
    for idx, (name, start) in enumerate(jobs):
        end = jobs[idx + 1][1] if idx + 1 < len(jobs) else len(lines)
        for row in range(start + 1, end):
            match = re.match(r"^(\s*)runs-on\s*:", lines[row])
            if not match or not re.search(r"\bself-hosted\b", lines[row].split("#", 1)[0]):
                continue
            col = len(match.group(1))
            endcol = len(lines[row].encode("utf-8"))
            finding = _finding(
                "self-hosted-runner", "runs on a self-hosted runner", "Medium", "High", path,
                "self-hosted runner used here", ["jobs", name, "runs-on"], row + 1,
                col, endcol, lines[row][col:], source=text,
            )
            finding["determinations"]["persona"] = "Auditor"
            loc = finding["locations"][0]["concrete"]["location"]
            loc["offset_span"] = {"start": offsets[row] + len(lines[row][:col].encode("utf-8")),
                                  "end": offsets[row] + len(lines[row].encode("utf-8"))}
            finding["locations"][0]["concrete"]["feature"] = lines[row]
            findings.append(finding)
    return findings


def concurrency_findings(text, path):
    """Report missing workflow-level concurrency in pedantic-capable modes."""
    from audit import _finding

    lines = text.splitlines()
    trigger = next((i for i, line in enumerate(lines) if line.startswith("on:")), None)
    if trigger is None or any(re.match(r"^concurrency\s*:", line) for line in lines):
        return []
    jobs_at = next((i for i, line in enumerate(lines) if re.match(r"^jobs\s*:", line)), None)
    if jobs_at is None:
        return []
    jobs = []
    offsets = []
    pos = 0
    for line in lines:
        offsets.append(pos)
        pos += len(line.encode("utf-8")) + 1
    for row in range(jobs_at + 1, len(lines)):
        match = re.match(r"^  ([\w-]+):\s*(?:#.*)?$", lines[row])
        if match:
            jobs.append((match.group(1), row))
    if not jobs:
        return []
    primary_line = lines[trigger]
    primary = _finding(
        "concurrency-limits", "insufficient job-level concurrency limits", "Low", "High", path,
        "workflow is missing concurrency setting", ["on"], trigger + 1, 0,
        len(primary_line.encode("utf-8")), primary_line.strip(), source=text,
    )
    primary["determinations"]["persona"] = "Pedantic"
    primary_loc = primary["locations"][0]
    primary_loc["concrete"]["location"]["offset_span"] = {
        "start": offsets[trigger], "end": offsets[trigger] + len(primary_line.encode("utf-8"))}
    primary_loc["symbolic"]["kind"] = "Primary"
    for name, row in jobs:
        related = _finding(
            "concurrency-limits", "insufficient job-level concurrency limits", "Low", "High", path,
            "job affected by missing workflow concurrency", ["jobs", name], row + 1, 2,
            2 + len(name), name, kind="Related", source=text,
        )
        related["determinations"]["persona"] = "Pedantic"
        loc = related["locations"][0]
        loc["symbolic"]["feature_kind"] = "KeyOnly"
        loc["concrete"]["location"]["offset_span"] = {
            "start": offsets[row] + 2, "end": offsets[row] + 2 + len(name.encode("utf-8"))}
        primary["locations"].append(loc)
    return [primary]


def pedantic_permission_findings(text, path):
    """Include the workflow-wide default permission grant in pedantic mode."""
    from audit import _permission_finding

    lines = text.splitlines()
    if not lines or any(re.match(r"^permissions\s*:", line) for line in lines):
        return []
    finding = _permission_finding(
        path, "default permissions used due to no permissions: block", [], "Primary",
        0, len(lines) - 1, 0, len(text.encode("utf-8")), text,
    )
    finding["determinations"]["persona"] = "Pedantic"
    return [finding]


def service_image_findings(text, path, pedantic=False):
    """Audit Docker service images in job definitions."""
    from audit import _finding

    lines = text.splitlines()
    offsets = []
    pos = 0
    for line in lines:
        offsets.append(pos)
        pos += len(line.encode("utf-8")) + 1
    jobs = []
    for row, line in enumerate(lines):
        match = re.match(r"^  ([\w-]+):\s*(?:#.*)?$", line)
        if match and any(re.match(r"^jobs\s*:", prev) for prev in lines[:row]):
            jobs.append((match.group(1), row))
    findings = []
    for job_index, (job, start) in enumerate(jobs):
        end = jobs[job_index + 1][1] if job_index + 1 < len(jobs) else len(lines)
        services = next((row for row in range(start + 1, end)
                         if re.match(r"^    services\s*:", lines[row])), None)
        if services is None:
            continue
        service_names = []
        for row in range(services + 1, end):
            name = re.match(r"^      ([\w-]+):\s*(?:#.*)?$", lines[row])
            if name:
                service_names.append((name.group(1), row))
        for service_index, (service, service_row) in enumerate(service_names):
            service_end = service_names[service_index + 1][1] if service_index + 1 < len(service_names) else end
            for row in range(service_row + 1, service_end):
                match = re.match(r"^(\s*)image\s*:\s*[\"']?([^\s\"']+)", lines[row])
                if not match:
                    continue
                image = match.group(2)
                leaf = image.rsplit("/", 1)[-1]
